Object.assign(window.EXAMPLES=window.EXAMPLES||{},{"mexicocity":{"t":"A city on a drained lake","c":"Mexico City, one of the largest cities in the Americas with over 20 million people in its metropolitan area, stands in a high valley about 2,240 metres above sea level, on the site of the Aztec capital Tenochtitlan. The lakes that once filled the valley were drained after the Spanish conquest, and today the city pumps so much water from the soft clay beneath it that parts are sinking, in some places by tens of centimetres a year, tilting buildings and cracking pipes. Its historic centre is a UNESCO World Heritage Site. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 220\" width=\"620\" height=\"220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"220\" rx=\"10\" fill=\"#fef3c7\"/><path d=\"M0,220V160Q150,170 310,160T620,170V220Z\" fill=\"#a16207\"/><ellipse cx=\"310\" cy=\"150\" rx=\"250\" ry=\"40\" fill=\"#bae6fd\" opacity=\".7\"/><rect x=\"200\" y=\"80\" width=\"40\" height=\"60\" fill=\"#78716c\"/><rect x=\"250\" y=\"60\" width=\"50\" height=\"80\" fill=\"#a8a29e\"/><rect x=\"310\" y=\"90\" width=\"60\" height=\"50\" fill=\"#78716c\"/><text x=\"310\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mexico City sits on a former lake bed, about 2,240 m up</text><text x=\"310\" y=\"206\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fef3c7\" font-family=\"system-ui,sans-serif\">The soft clay is sinking up to tens of cm a year in places</text></svg>","c":"Mexico City on its old lake bed (simplified)"}]},"saopaulo":{"t":"São Paulo’s growth","c":"São Paulo is the largest city in Brazil and in the Southern Hemisphere, with over 22 million people in its metropolitan area. Founded by Jesuit missionaries in 1554, it grew rich in the 19th century on coffee and then on industry. Millions of immigrants arrived, especially from Italy, Portugal, Spain, Lebanon and Japan; it is home to the largest Japanese community outside Japan. Today it is Brazil’s financial centre, a sprawling city of skyscrapers famous for its food, culture and traffic jams.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1554</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">São Paulo founded by Jesuit missionaries</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1800s</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Coffee boom brings wealth and immigrants</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Early 1900s</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Large Italian, Japanese and other immigration</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Today</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Over 22 million people in the metropolitan area</text></svg>","c":"Milestones in São Paulo’s history"}]},"centralasia":{"t":"The five Central Asian republics","c":"Central Asia is usually taken to mean five countries that became independent when the Soviet Union broke up in 1991: Kazakhstan, Kyrgyzstan, Tajikistan, Turkmenistan and Uzbekistan. Their names share the Persian ending ‘-stan’, meaning ‘land of’. The region, a crossroads of the Silk Road, includes vast steppes, deserts and the Tian Shan and Pamir mountains, and ancient cities such as Samarkand and Bukhara. Kazakhstan, the world’s largest landlocked country, is bigger than Western Europe.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 118\" width=\"610\" height=\"118\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kazakhstan</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kyrgyzstan</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tajikistan</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Turkmenistan</text><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"224\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Uzbekistan</text><text x=\"224\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text></svg>","c":"The five republics"}]},"carabao":{"t":"The carabao","c":"The carabao is a domestic swamp-type water buffalo and the national animal of the Philippines. For centuries it has pulled ploughs through flooded rice fields, hauled carts and provided milk, meat and hides, earning it the title of the Filipino farmer’s best friend. Because it has few sweat glands, it wallows in mud and water to keep cool. Water buffalo were domesticated in Asia thousands of years ago, and similar swamp buffalo are used across Southeast Asia and southern China. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 210\" width=\"620\" height=\"210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#ecfccb\"/><path d=\"M120,140Q130,80 240,80Q380,80 420,120L430,150Z\" fill=\"#475569\"/><circle cx=\"440\" cy=\"110\" r=\"30\" fill=\"#475569\"/><path d=\"M420,90Q380,40 330,60M460,90Q500,40 550,60\" fill=\"none\" stroke=\"#1c1917\" stroke-width=\"10\" stroke-linecap=\"round\"/><rect x=\"150\" y=\"140\" width=\"16\" height=\"50\" fill=\"#475569\"/><rect x=\"200\" y=\"140\" width=\"16\" height=\"50\" fill=\"#475569\"/><rect x=\"350\" y=\"140\" width=\"16\" height=\"50\" fill=\"#475569\"/><rect x=\"400\" y=\"140\" width=\"16\" height=\"50\" fill=\"#475569\"/><rect y=\"190\" width=\"620\" height=\"20\" fill=\"#65a30d\"/><text x=\"440\" y=\"40\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Huge swept-back horns</text><text x=\"250\" y=\"74\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wallows in mud to stay cool</text></svg>","c":"A carabao, simplified"}]},"tamaraw":{"t":"The tamaraw","c":"The tamaraw is a small, stocky wild buffalo found only on the island of Mindoro in the Philippines. Unlike the domestic carabao, it is wild, shy and mostly active at night, with short, straight horns pointing up in a V shape. It once roamed across the island, but hunting, disease brought by cattle and the loss of its grassland and forest habitat reduced it to a few hundred animals. It is critically endangered, with recent counts finding around 600 in Mounts Iglit–Baco Natural Park and a few other sites. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 210\" width=\"620\" height=\"210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#ecfccb\"/><path d=\"M140,140Q150,90 260,90Q380,90 410,120L420,150Z\" fill=\"#1c1917\"/><circle cx=\"430\" cy=\"115\" r=\"26\" fill=\"#1c1917\"/><path d=\"M420,92L410,52M440,92L450,52\" stroke=\"#57534e\" stroke-width=\"8\" stroke-linecap=\"round\"/><rect x=\"170\" y=\"140\" width=\"14\" height=\"44\" fill=\"#1c1917\"/><rect x=\"210\" y=\"140\" width=\"14\" height=\"44\" fill=\"#1c1917\"/><rect x=\"350\" y=\"140\" width=\"14\" height=\"44\" fill=\"#1c1917\"/><rect x=\"390\" y=\"140\" width=\"14\" height=\"44\" fill=\"#1c1917\"/><rect y=\"184\" width=\"620\" height=\"26\" fill=\"#65a30d\"/><text x=\"430\" y=\"40\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Short, straight, V-shaped horns</text><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Found only on Mindoro; about 600 left</text></svg>","c":"A tamaraw, simplified"}]},"cockatoo":{"t":"Some threatened Philippine animals","c":"The Philippine cockatoo, or katala, is a white parrot with a red patch under its tail, found only in the Philippines. Trapping for the pet trade and forest loss reduced it to perhaps a thousand birds, mostly on Palawan, where community wardens, some of them former poachers, now protect nests. It is one of many Philippine species found nowhere else and threatened with extinction. Conservation statuses follow the IUCN Red List and may change.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 232\" width=\"610\" height=\"232\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine eagle</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Critically endangered</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#1c1917\" fill-opacity=\".2\" stroke=\"#1c1917\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tamaraw</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Critically endangered</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#94a3b8\" fill-opacity=\".2\" stroke=\"#94a3b8\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine cockatoo</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Critically endangered</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#57534e\" fill-opacity=\".2\" stroke=\"#57534e\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Visayan warty pig</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Critically endangered</text><rect x=\"10\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine tarsier</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Near threatened</text><rect x=\"310\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine mouse-deer</text><text x=\"324\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Endangered</text></svg>","c":"Status of some species found only in the Philippines"}]},"mousedeer":{"t":"The Philippine mouse-deer","c":"The Philippine mouse-deer, or pilandok, lives only on Balabac and a few nearby islands south of Palawan. Despite its name it is neither a mouse nor a true deer but a chevrotain, one of the smallest hoofed mammals in the world, about 40 to 50 centimetres long with legs as thin as pencils. It has no antlers; males have small tusk-like canine teeth instead. In Filipino folklore the pilandok is a clever trickster. It is endangered because of hunting and habitat loss. Simplified.","items":[{"s":"<svg viewBox=\"0 0 420 230\" width=\"420\" height=\"230\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:400px;max-width:100%;height:auto\"><rect width=\"420\" height=\"230\" rx=\"10\" fill=\"#ecfccb\"/><ellipse cx=\"200\" cy=\"130\" rx=\"70\" ry=\"44\" fill=\"#a16207\"/><circle cx=\"276\" cy=\"110\" r=\"26\" fill=\"#a16207\"/><circle cx=\"286\" cy=\"104\" r=\"4\" fill=\"#0f172a\"/><path d=\"M150,166V210\" stroke=\"#a16207\" stroke-width=\"5\"/><path d=\"M180,166V210\" stroke=\"#a16207\" stroke-width=\"5\"/><path d=\"M220,166V210\" stroke=\"#a16207\" stroke-width=\"5\"/><path d=\"M250,166V210\" stroke=\"#a16207\" stroke-width=\"5\"/><path d=\"M292,116l12,4\" stroke=\"#78350f\" stroke-width=\"3\"/><text x=\"210\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About 40 cm long: the size of a house cat</text><text x=\"210\" y=\"224\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Legs as thin as a pencil</text></svg>","c":"A mouse-deer, simplified"}]},"cloudrats":{"t":"Cloud rats","c":"Cloud rats are large, furry, mostly tree-dwelling rodents found only in the Philippines, especially in the mountain forests of Luzon. The northern giant cloud rat can weigh over 2 kilograms and measure about 75 centimetres including its long bushy tail. They feed on leaves, shoots and fruit and are active at night. New species of cloud rat are still being discovered by scientists in remote mountains, showing how much remains unknown about Philippine biodiversity. Some species are threatened by forest loss and hunting. Simplified.","items":[{"s":"<svg viewBox=\"0 0 420 230\" width=\"420\" height=\"230\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:400px;max-width:100%;height:auto\"><rect width=\"420\" height=\"230\" rx=\"10\" fill=\"#ecfccb\"/><path d=\"M0,60H420\" stroke=\"#78350f\" stroke-width=\"10\"/><ellipse cx=\"200\" cy=\"120\" rx=\"70\" ry=\"46\" fill=\"#57534e\"/><circle cx=\"270\" cy=\"96\" r=\"26\" fill=\"#57534e\"/><circle cx=\"280\" cy=\"90\" r=\"4\" fill=\"#0f172a\"/><path d=\"M130,120Q60,150 70,200\" fill=\"none\" stroke=\"#57534e\" stroke-width=\"14\" stroke-linecap=\"round\"/><path d=\"M170,84V62\" stroke=\"#57534e\" stroke-width=\"7\"/><path d=\"M230,84V62\" stroke=\"#57534e\" stroke-width=\"7\"/><text x=\"210\" y=\"214\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bushy-tailed; can weigh over 2 kg</text></svg>","c":"A giant cloud rat on a branch, simplified"}]},"wartypig":{"t":"The Visayan warty pig","c":"The Visayan warty pig is a wild pig found only on a few islands of the western Visayas, mainly Negros and Panay. Males are known for three pairs of fleshy warts on the face and, in the breeding season, a long spiky mane along the back. It is critically endangered, having lost over 95 percent of its former range to deforestation and hunting, and it no longer survives on several islands where it once lived. Breeding programmes in the Philippines and zoos abroad aim to save it. Simplified.","items":[{"s":"<svg viewBox=\"0 0 420 230\" width=\"420\" height=\"230\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:400px;max-width:100%;height:auto\"><rect width=\"420\" height=\"230\" rx=\"10\" fill=\"#ecfccb\"/><ellipse cx=\"200\" cy=\"130\" rx=\"90\" ry=\"48\" fill=\"#57534e\"/><path d=\"M110,120Q80,100 70,130Q80,150 110,140Z\" fill=\"#57534e\"/><circle cx=\"95\" cy=\"118\" r=\"4\" fill=\"#0f172a\"/><path d=\"M150,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M156,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M162,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M168,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M174,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M180,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M186,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M192,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M198,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M204,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M210,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M216,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M222,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M228,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><rect x=\"140\" y=\"170\" width=\"10\" height=\"36\" fill=\"#57534e\"/><rect x=\"170\" y=\"170\" width=\"10\" height=\"36\" fill=\"#57534e\"/><rect x=\"240\" y=\"170\" width=\"10\" height=\"36\" fill=\"#57534e\"/><rect x=\"270\" y=\"170\" width=\"10\" height=\"36\" fill=\"#57534e\"/><circle cx=\"105\" cy=\"128\" r=\"4\" fill=\"#a8a29e\"/><circle cx=\"118\" cy=\"132\" r=\"4\" fill=\"#a8a29e\"/><text x=\"210\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Males grow a spiky mane and facial warts</text></svg>","c":"A male Visayan warty pig, simplified"}]},"swiftlets":{"t":"Edible-nest swiftlets","c":"Edible-nest swiftlets are small birds of Southeast Asia that nest high on the walls of dark caves, navigating in darkness by echolocation, using clicking sounds. They build cup-shaped nests almost entirely from strands of their own saliva, which hardens on contact with air. The nests are harvested to make bird’s nest soup, a costly delicacy in Chinese cuisine, at times among the most expensive animal products in the world. Overharvesting has harmed some colonies, so many nests now come from purpose-built swiftlet houses. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 210\" width=\"620\" height=\"210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#0b1026\"/><path d=\"M0,0H620V60Q500,40 310,60Q120,80 0,60Z\" fill=\"#57534e\"/><path d=\"M94,62Q120,92 146,62\" fill=\"#fef3c7\" stroke=\"#d6d3d1\"/><path d=\"M184,62Q210,92 236,62\" fill=\"#fef3c7\" stroke=\"#d6d3d1\"/><path d=\"M274,62Q300,92 326,62\" fill=\"#fef3c7\" stroke=\"#d6d3d1\"/><path d=\"M364,62Q390,92 416,62\" fill=\"#fef3c7\" stroke=\"#d6d3d1\"/><path d=\"M454,62Q480,92 506,62\" fill=\"#fef3c7\" stroke=\"#d6d3d1\"/><text x=\"310\" y=\"150\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Nests made almost entirely of the birds’ own hardened saliva</text><text x=\"310\" y=\"172\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\" fill=\"#cbd5e1\" font-family=\"system-ui,sans-serif\">Stuck to cave walls; used for bird’s nest soup</text></svg>","c":"Swiftlet nests on a cave ceiling"}]},"seasnakes":{"t":"Sea snakes","c":"Sea snakes are venomous reptiles that live in warm tropical waters of the Indian and Pacific oceans. They evolved from land snakes and have flattened, paddle-shaped tails for swimming. They must surface to breathe air, but some can stay under for over an hour, partly by absorbing oxygen through their skin. Most give birth to live young at sea. Their venom is powerful, but they are generally not aggressive and bites are rare. Sea kraits, banded black and blue, come ashore to rest and lay eggs. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"180\" rx=\"10\" fill=\"#bae6fd\"/><path d=\"M30,90Q120,50 210,90T390,90Q470,60 520,90\" fill=\"none\" stroke=\"#1d4ed8\" stroke-width=\"18\" stroke-linecap=\"round\"/><path d=\"M50,82v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M98,90.4v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M146,91.1v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M194,83.4v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M242,74.4v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M290,72.4v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M338,79.2v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M386,88.6v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M434,91.9v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M482,86.1v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M520,90L590,60L575,90L590,120Z\" fill=\"#1d4ed8\"/><text x=\"555\" y=\"150\" text-anchor=\"end\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Paddle-shaped tail for swimming</text><text x=\"120\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Must surface to breathe air</text></svg>","c":"A banded sea snake, simplified"}]},"monitorlizards":{"t":"Some big monitor lizards","c":"Monitor lizards are a group of about 80 species found in Africa, Asia and Australia, including the Komodo dragon, the largest living lizard. They are active hunters with long necks, strong claws and forked tongues that flick out to taste the air, like snakes. Many are good swimmers. The Asian water monitor is common across South and Southeast Asia, including the Philippines, where it is called bayawak, and often lives near people. Lengths are approximate maximums.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#57534e\" fill-opacity=\".2\" stroke=\"#57534e\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Komodo dragon</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Indonesia: up to 3 m</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#4d7c0f\" fill-opacity=\".2\" stroke=\"#4d7c0f\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Asian water monitor</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">South and Southeast Asia: up to 2.5 m</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Perentie</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Australia: up to 2.5 m</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#65a30d\" fill-opacity=\".2\" stroke=\"#65a30d\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nile monitor</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Africa: up to 2 m</text></svg>","c":"Four large monitor lizards and where they live"}]},"spice":{"t":"The spice trade through history","c":"For thousands of years, spices such as pepper, cinnamon, cloves and nutmeg were among the world’s most valuable goods, used to flavour and preserve food, in medicine and in religious rituals. Many came from India, Sri Lanka and the Moluccas, the ‘Spice Islands’ of Indonesia. Arab, Indian and Chinese traders carried them across the Indian Ocean and overland. Europe’s desire to reach the sources directly drove the Age of Exploration and the founding of colonial trading empires such as the Dutch and English East India Companies.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#ea580c\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">3500–2000 BC</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mesopotamian merchants trade spices</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#ea580c\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1st c. AD</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Roman ships sail to India</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#ea580c\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">800s–1400s</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Arab and Indian traders dominate the Indian Ocean</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#ea580c\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1498</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Vasco da Gama reaches India by sea</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#ea580c\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1600s</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dutch and English East India Companies</text></svg>","c":"Milestones of the spice trade"}]},"agri":{"t":"Where farming began","c":"Around 12,000 years ago, people in several parts of the world independently began to farm, growing crops and keeping animals instead of relying only on hunting and gathering. The earliest known farming arose in the Fertile Crescent of the Middle East, and later in China, Mesoamerica, the Andes, New Guinea and parts of Africa, each with its own crops. Farming allowed people to settle in villages, populations to grow and, eventually, cities, writing and states to develop. Dates are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 232\" width=\"610\" height=\"232\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fertile Crescent</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wheat, barley, lentils; sheep, goats</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">China</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Rice, millet; pigs</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mesoamerica</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Maize, beans, squash</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Andes</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Potatoes, quinoa; llamas</text><rect x=\"10\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">New Guinea</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Taro, bananas, sugarcane</text><rect x=\"310\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"324\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Africa</text><text x=\"324\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sorghum, yams; cattle</text></svg>","c":"Independent centres of early farming and their crops"}]},"fish":{"t":"Farming fish now rivals catching them","c":"For most of history, people ate fish caught from the wild. Since the 1990s the wild catch has levelled off, as many fish stocks are fully exploited or overfished, while aquaculture, the farming of fish, shellfish and seaweed, has grown rapidly and now produces as much as or more than fishing. China is by far the largest producer. Aquaculture eases pressure on wild stocks but can cause pollution and disease if poorly managed. Figures are approximate global totals of aquatic animals, from the UN Food and Agriculture Organization.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 184\" width=\"620\" height=\"184\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"160\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wild catch, 1990</text><rect x=\"170\" y=\"12\" width=\"274.5\" height=\"28\" rx=\"5\" fill=\"#0891b2\"/><text x=\"452.468085106383\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 86 million metric tons</text><text x=\"160\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Farmed, 1990</text><rect x=\"170\" y=\"52\" width=\"41.5\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"219.48936170212767\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 13 million</text><text x=\"160\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wild catch, 2022</text><rect x=\"170\" y=\"92\" width=\"290.4\" height=\"28\" rx=\"5\" fill=\"#0891b2\"/><text x=\"468.4255319148936\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 91 million</text><text x=\"160\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Farmed, 2022</text><rect x=\"170\" y=\"132\" width=\"300.0\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"478\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 94 million</text></svg>","c":"Global fish and seafood production"}]},"potato":{"t":"The potato’s journey","c":"The potato was first domesticated in the Andes of South America, around Lake Titicaca, about 8,000 years ago, where thousands of varieties are still grown. Spanish conquerors brought it to Europe in the late 1500s. It became a staple food, feeding growing populations in Ireland, Germany, Russia and beyond, though Ireland’s heavy reliance on it made the potato blight of 1845–49 a devastating famine. Today it is one of the world’s most important food crops, with China and India the largest producers.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><rect x=\"20\" y=\"60\" width=\"170\" height=\"80\" rx=\"10\" fill=\"#c4b5fd\"/><text x=\"105\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Andes, 8,000 years ago</text><text x=\"105\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">first domesticated</text><path d=\"M190,100H222\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M230,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"230\" y=\"60\" width=\"160\" height=\"80\" rx=\"10\" fill=\"#fde68a\"/><text x=\"310\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Europe, 1500s</text><text x=\"310\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">brought by the Spanish</text><path d=\"M390,100H422\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M430,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"430\" y=\"60\" width=\"170\" height=\"80\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"515\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Worldwide today</text><text x=\"515\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">a top food crop</text></svg>","c":"From the Andes to the world"}]},"sugar":{"t":"How sugar is made","c":"Most of the world’s sugar comes from sugarcane, a tall tropical grass first domesticated in New Guinea, and sugar beet, grown in cooler climates. The cane is crushed to extract its sweet juice, which is boiled down into syrup until sugar crystals form; the crystals are separated from the leftover molasses and refined into white sugar. Sugar transformed world history: the demand for it drove the Atlantic slave trade and the plantation economies of the Caribbean and Brazil. Health bodies recommend limiting added sugar. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#f0fdf4\"/><rect x=\"20\" y=\"60\" width=\"140\" height=\"80\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"90\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Sugarcane</text><text x=\"90\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">or sugar beet</text><path d=\"M160,100H182\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M190,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"190\" y=\"60\" width=\"120\" height=\"80\" rx=\"10\" fill=\"#e5e7eb\"/><text x=\"250\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Crushed</text><text x=\"250\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">juice extracted</text><path d=\"M310,100H332\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M340,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"340\" y=\"60\" width=\"120\" height=\"80\" rx=\"10\" fill=\"#fde68a\"/><text x=\"400\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Boiled</text><text x=\"400\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">into syrup</text><path d=\"M460,100H482\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M490,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"490\" y=\"60\" width=\"110\" height=\"80\" rx=\"10\" fill=\"#f8fafc\"/><text x=\"545\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Crystals</text><text x=\"545\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">refined sugar</text></svg>","c":"From sugarcane to sugar"}]},"maize":{"t":"From wild grass to maize","c":"Maize, or corn, was domesticated about 9,000 years ago in southern Mexico from a wild grass called teosinte, which has only a few small, hard kernels. Over thousands of years farmers selected plants with more and softer kernels, creating the large cobs we know. Maize became the staple of the Maya, Aztecs and many other peoples of the Americas, and after 1492 it spread around the world. Today it is the most produced grain crop on Earth, used for food, animal feed and fuel. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><path d=\"M60,170V40\" stroke=\"#65a30d\" stroke-width=\"4\"/><path d=\"M60,120q-40,-10 -44,-40M60,110q30,-14 30,-50\" stroke=\"#65a30d\" stroke-width=\"3\" fill=\"none\"/><ellipse cx=\"62\" cy=\"50\" rx=\"5\" ry=\"12\" fill=\"#facc15\"/><text x=\"20\" y=\"190\" text-anchor=\"start\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Teosinte: a few hard kernels</text><path d=\"M380,170V30\" stroke=\"#65a30d\" stroke-width=\"10\"/><ellipse cx=\"420\" cy=\"90\" rx=\"22\" ry=\"60\" fill=\"#facc15\"/><path d=\"M402,44H438\" stroke=\"#ca8a04\"/><path d=\"M402,56H438\" stroke=\"#ca8a04\"/><path d=\"M402,68H438\" stroke=\"#ca8a04\"/><path d=\"M402,80H438\" stroke=\"#ca8a04\"/><path d=\"M402,92H438\" stroke=\"#ca8a04\"/><path d=\"M402,104H438\" stroke=\"#ca8a04\"/><path d=\"M402,116H438\" stroke=\"#ca8a04\"/><path d=\"M402,128H438\" stroke=\"#ca8a04\"/><text x=\"600\" y=\"190\" text-anchor=\"end\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Modern maize: hundreds per cob</text><path d=\"M150,90H312\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M320,90l-10,-6v12z\" fill=\"currentColor\"/></svg>","c":"Teosinte compared with modern maize (simplified)"}]},"beatles":{"t":"The Beatles’ story","c":"The Beatles, formed in Liverpool in 1960, with John Lennon, Paul McCartney, George Harrison and Ringo Starr as the famous line-up, became the best-selling music act of all time. From 1963 their hits and the hysteria of Beatlemania swept Britain and then America, where their 1964 television appearance drew about 73 million viewers. In the studio they pioneered new recording techniques and expanded what pop albums could be. They broke up in 1970, but their songs remain among the most covered ever written.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1960</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The Beatles form in Liverpool</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1963</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">‘She Loves You’; Beatlemania begins</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1964</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Appear on The Ed Sullivan Show in the US</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1967</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sgt. Pepper’s Lonely Hearts Club Band</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1970</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The band breaks up</text></svg>","c":"Milestones of the Beatles"}]},"labor":{"t":"How work has changed","c":"The kind of work most people do has changed dramatically. For most of human history people hunted and gathered; then most became farmers. The Industrial Revolution moved millions into factories, often with long hours and child labour, which led workers to form trade unions and win rights such as the eight-hour day and the weekend. Today, in richer countries, most people work in services such as health, education, retail and offices, while new technologies are again reshaping jobs. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 340\" width=\"600\" height=\"340\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hunting and gathering</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Most of human history</text><rect x=\"10\" y=\"76\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#65a30d\" fill-opacity=\".2\" stroke=\"#65a30d\"/><text x=\"24\" y=\"104\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Farming</text><text x=\"24\" y=\"124\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">From about 12,000 years ago</text><rect x=\"10\" y=\"142\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#475569\" fill-opacity=\".2\" stroke=\"#475569\"/><text x=\"24\" y=\"170\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Factory work</text><text x=\"24\" y=\"190\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Industrial Revolution, 1700s–</text><rect x=\"10\" y=\"208\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"236\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Services and offices</text><text x=\"24\" y=\"256\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">20th century–</text><rect x=\"10\" y=\"274\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"302\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Digital and remote work</text><text x=\"24\" y=\"322\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">21st century</text></svg>","c":"Major eras of work"}]},"michel":{"t":"Michelangelo’s great works","c":"Michelangelo Buonarroti was a sculptor, painter, architect and poet of the Italian Renaissance, considered one of the greatest artists of all time. He carved the Pietà in his early twenties and the 5-metre marble David from a single block that others had rejected. Though he thought of himself mainly as a sculptor, he spent four years painting the ceiling of the Sistine Chapel in the Vatican, covering over 500 square metres with scenes from Genesis, including the Creation of Adam, and later designed the dome of St Peter’s.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1475</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Caprese, Italy</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1498–99</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pietà, St Peter’s Basilica</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1501–04</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">David, Florence</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1508–12</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sistine Chapel ceiling</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1546</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chief architect of St Peter’s Basilica</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1564</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies in Rome, aged 88</text></svg>","c":"Milestones in Michelangelo’s life"}]},"stagemagic":{"t":"How misdirection works","c":"Stage magicians create the illusion of the impossible using sleight of hand, hidden devices and psychology. A key technique is misdirection: guiding the audience’s attention to one place, with a gesture, a glance, a joke or a flash of movement, while the secret move happens somewhere else. Research by psychologists shows that people miss surprisingly large things when their attention is elsewhere. Famous magicians include Harry Houdini, the escape artist, and David Copperfield. Magicians traditionally guard their secrets. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#1c1917\"/><rect x=\"40\" y=\"40\" width=\"200\" height=\"120\" fill=\"#fef3c7\"/><path d=\"M40,160L240,40\" stroke=\"#57534e\" stroke-width=\"2\" stroke-dasharray=\"5 4\"/><text x=\"140\" y=\"190\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fde68a\" font-family=\"system-ui,sans-serif\">Magician’s side</text><circle cx=\"430\" cy=\"100\" r=\"50\" fill=\"#7c3aed\"/><text x=\"430\" y=\"190\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Misdirection: the audience looks here</text><path d=\"M330,100H260\" stroke=\"#facc15\" stroke-width=\"3\"/><text x=\"140\" y=\"28\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fde68a\" font-family=\"system-ui,sans-serif\">while the secret happens here</text></svg>","c":"Attention drawn away from the secret move"}]},"detective":{"t":"Kinds of mystery stories","c":"Detective fiction began with Edgar Allan Poe’s stories about the investigator Auguste Dupin in the 1840s and was made hugely popular by Arthur Conan Doyle’s Sherlock Holmes. In the ‘golden age’ between the world wars, writers such as Agatha Christie, the best-selling novelist of all time, perfected the puzzle-like whodunit. Later sub-genres include American hardboiled fiction with tough private eyes, cosy mysteries, police procedurals and Scandinavian crime fiction. Readers are invited to solve the mystery alongside the detective.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Whodunit</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Find the culprit among suspects</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#334155\" fill-opacity=\".2\" stroke=\"#334155\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hardboiled</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tough private eyes in gritty cities</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cosy mystery</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Small towns, amateur sleuths</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Police procedural</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Realistic police investigation</text></svg>","c":"Four types of mystery fiction"}]},"scifi":{"t":"Common science fiction themes","c":"Science fiction imagines how science and technology might change the world, often to explore human questions. Mary Shelley’s Frankenstein of 1818 is often called the first science fiction novel; Jules Verne and H. G. Wells followed with submarines, time machines and alien invasions. Writers such as Isaac Asimov, who formulated three laws of robotics, Ursula K. Le Guin, Octavia Butler and Liu Cixin have explored robots, space travel, alien contact and future societies. Many real inventions, from submarines to video calls, appeared in science fiction first.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 118\" width=\"610\" height=\"118\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Robots and AI</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Space travel</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Time travel</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Aliens</text><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"224\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dystopian futures</text><text x=\"224\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"424\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cyberpunk</text><text x=\"424\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text></svg>","c":"Six recurring themes"}]},"circus":{"t":"Acts of the circus","c":"The modern circus began in London in 1768, when Philip Astley, a former cavalryman, performed horse-riding tricks in a ring about 13 metres across, still the standard size today, and soon added acrobats, clowns and jugglers. Travelling circuses spread across Europe and America, famously Barnum & Bailey. Animal acts, once central, have been banned or restricted in many countries over welfare concerns. Contemporary circuses such as Cirque du Soleil focus on acrobatics, music and theatre. Chinese acrobatics has its own ancient tradition.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ringmaster</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Introduces the acts</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Acrobats and aerialists</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Trapeze and tightrope</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Clowns</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Comedy between acts</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Jugglers</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Skill and timing</text></svg>","c":"Classic circus performers"}]},"musicals":{"t":"The parts of a musical","c":"Musical theatre combines songs, spoken dialogue, acting and dance to tell a story. It grew from opera, operetta and vaudeville, and flowered on Broadway in New York and the West End in London in the 20th century, with shows by Rodgers and Hammerstein, Stephen Sondheim and Andrew Lloyd Webber. The Phantom of the Opera ran on Broadway for 35 years, the longest run in its history. Modern hits such as Hamilton mix in hip hop and other styles. Songs often reveal what characters feel when words alone are not enough.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Overture</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Instrumental opening</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Songs</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tell the story and show feelings</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dialogue</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Spoken scenes between songs</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dance numbers</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Choreography</text></svg>","c":"Building blocks of a musical"}]},"modernart":{"t":"Movements in modern art","c":"From the late 1800s artists broke away from realistic painting in a rapid series of movements. Impressionists captured light; Fauvists used wild colour; Cubists such as Picasso and Braque showed several viewpoints at once; Dadaists challenged what art could be; Surrealists like Salvador Dalí painted dreams; Abstract Expressionists such as Jackson Pollock dripped and splashed paint; and Pop artists like Andy Warhol drew on advertising and celebrity. Each reacted to what came before and to a changing world. Dates are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 372\" width=\"640\" height=\"372\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"356\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1800s</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Romanticism: emotion and nature</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1870s</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Impressionism: light and colour</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1905</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fauvism: wild colour</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1907</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cubism: many viewpoints</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1916</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dada: anti-art</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1924</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Surrealism: dreams</text><circle cx=\"140\" cy=\"286\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"291\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1940s</text><text x=\"156\" y=\"291\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Abstract Expressionism</text><circle cx=\"140\" cy=\"328\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"333\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1960s</text><text x=\"156\" y=\"333\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pop Art</text></svg>","c":"Selected movements and roughly when they began"}]},"chineseart":{"t":"Traditional Chinese art forms","c":"Chinese art has a continuous history of thousands of years. Calligraphy, writing characters with brush and ink, is considered one of the highest arts, closely tied to painting, which favoured landscapes of mountains and water, called shan shui, often accompanied by poems. China invented porcelain, and blue-and-white ware from the kilns of Jingdezhen was exported worldwide; in English, fine porcelain is still called china. Jade carving, bronze casting, silk weaving and lacquer are other celebrated traditions.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#1c1917\" fill-opacity=\".2\" stroke=\"#1c1917\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Calligraphy</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Brush writing as fine art</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Landscape painting</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mountains and water, shan shui</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Porcelain</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blue-and-white ware from Jingdezhen</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#0d9488\" fill-opacity=\".2\" stroke=\"#0d9488\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Jade carving</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Prized for thousands of years</text></svg>","c":"Four celebrated art forms"}]},"africanart":{"t":"Some traditions of African art","c":"Africa’s 54 countries and thousands of peoples have enormously varied artistic traditions. Carved wooden masks and figures, often used in ceremonies, inspired European artists such as Picasso. Kente cloth from Ghana uses woven patterns with symbolic meanings. The Benin Bronzes, thousands of brass plaques and sculptures made in the Kingdom of Benin, were looted by British troops in 1897; some are now being returned to Nigeria. Rock paintings in the Sahara and southern Africa date back thousands of years.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Masks</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Worn in ceremonies and dances</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kente cloth</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Woven strips of the Ashanti and Ewe, Ghana</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#b45309\" fill-opacity=\".2\" stroke=\"#b45309\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Benin Bronzes</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Brass plaques from the Kingdom of Benin</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#78350f\" fill-opacity=\".2\" stroke=\"#78350f\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Rock art</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ancient Saharan and San paintings</text></svg>","c":"Four African art traditions"}]},"kpop":{"t":"The rise of K-pop","c":"K-pop, South Korean popular music, grew from the early 1990s into a global phenomenon. Entertainment companies train young performers, called idols, for years in singing, dancing and languages before they debut in groups known for polished choreography, striking visuals and close engagement with fans online. PSY’s ‘Gangnam Style’ became YouTube’s first video to pass a billion views in 2012, and groups such as BTS and BLACKPINK have topped charts worldwide. K-pop is part of the wider Korean Wave, or Hallyu, along with dramas and films.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1992</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Seo Taiji and Boys spark modern K-pop</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1996</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First idol groups such as H.O.T.</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2012</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">PSY’s ‘Gangnam Style’: first video to 1 billion views</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2017–</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">BTS and BLACKPINK top global charts</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2020</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">BTS reach No. 1 on the US Billboard Hot 100</text></svg>","c":"Milestones in K-pop’s rise"}]},"bollywood":{"t":"Hallmarks of Bollywood films","c":"Bollywood is the Hindi-language film industry based in Mumbai, formerly Bombay. It is part of India’s vast cinema, which, including films in Tamil, Telugu and other languages, produces more films each year than any other country. Classic Bollywood films often blend romance, action, comedy and drama in one story, with elaborate song-and-dance numbers, and many run around three hours with an interval. Stars such as Amitabh Bachchan and Shah Rukh Khan have huge followings across South Asia and the world.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Song and dance</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Musical numbers are central</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Long running time</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Often around 2.5–3 hours, with an interval</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Many genres in one</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Romance, action, comedy, drama</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Huge output</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">India makes more films than any other country</text></svg>","c":"Typical features of Bollywood films"}]},"childlit":{"t":"Stages of children’s books","c":"Children’s literature ranges from board books for babies to novels for teenagers. Picture books tell stories through words and illustrations together; early readers help children learning to read; middle-grade novels suit readers of about 8 to 12; and young adult fiction, with teenage characters, is widely read by adults too. Classics include Alice’s Adventures in Wonderland, The Little Prince and the Harry Potter series, one of the best-selling book series in history. Reading for pleasure in childhood is linked to better outcomes in school.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Picture books</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Words and pictures together</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Early readers</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Short sentences for new readers</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Middle grade</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About ages 8–12</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Young adult</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Teenage characters and themes</text></svg>","c":"Common categories by age"}]},"comedy":{"t":"Kinds of comedy","c":"Comedy is as old as drama itself. In ancient Athens, Aristophanes wrote satirical plays mocking politicians; Shakespeare wrote comedies of mistaken identity; silent-film stars such as Charlie Chaplin and Buster Keaton perfected slapstick; and stand-up comedians and television sitcoms became staples of modern entertainment. Theories of why we laugh include surprise at the unexpected, a sense of superiority, and relief of tension. Humour varies greatly between cultures, but laughter itself is universal and helps people bond.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Slapstick</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Physical comedy, falls and chases</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Satire</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mocks the powerful</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stand-up</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A comedian alone on stage</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sitcom</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Situation comedy series</text></svg>","c":"Four forms of comedy"}]},"streetart":{"t":"Forms of street art","c":"Street art is art made in public spaces, often without permission. Modern graffiti grew in New York in the 1970s, as young writers sprayed tags and colourful pieces on subway trains and walls, alongside the rise of hip hop. Artists such as Keith Haring and Jean-Michel Basquiat moved from the streets into galleries, and the anonymous British artist Banksy became famous for satirical stencils. Many cities now commission large murals, while unauthorised graffiti remains illegal and debated as art or vandalism.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#1c1917\" fill-opacity=\".2\" stroke=\"#1c1917\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Graffiti tags</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stylised signatures</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Murals</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Large painted walls, often commissioned</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stencils</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sprayed through cut-out shapes</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Paste-ups</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Printed posters glued to walls</text></svg>","c":"Four common forms"}]},"tattoo":{"t":"Tattoo traditions around the world","c":"Tattooing is one of the oldest art forms: Ötzi, a man preserved in an Alpine glacier for over 5,000 years, had 61 tattoos. Many cultures developed their own traditions with deep meanings, from Japanese irezumi and Māori tā moko, which records ancestry, to Samoan pe’a and the hand-tapped batok of the Kalinga people of the northern Philippines, kept alive by Apo Whang-od. The English word tattoo comes from the Polynesian ‘tatau’. Today tattoos are popular worldwide, made with electric machines.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Irezumi</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Japan: full-body designs</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#1c1917\" fill-opacity=\".2\" stroke=\"#1c1917\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tā moko</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Māori facial tattoos</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Batok</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kalinga hand-tapped tattoos, Philippines</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pe’a</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Samoan tattoo from waist to knees</text></svg>","c":"Four traditional tattoo styles"}]},"rembrandt":{"t":"Rembrandt’s art","c":"Rembrandt van Rijn, who lived from 1606 to 1669, was the greatest painter of the Dutch Golden Age. He was a master of chiaroscuro, using pools of warm light against deep shadow to give his figures drama and inner life. He painted, drew and etched about 80 self-portraits, an unusually honest record of himself from youth to old age. His huge group portrait known as The Night Watch, completed in 1642, hangs in Amsterdam’s Rijksmuseum. Despite early fame, he died in poverty.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dramatic light</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Strong chiaroscuro</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#78350f\" fill-opacity=\".2\" stroke=\"#78350f\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Self-portraits</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Around 80 across his life</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#57534e\" fill-opacity=\".2\" stroke=\"#57534e\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Etchings</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Master printmaker</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#1c1917\" fill-opacity=\".2\" stroke=\"#1c1917\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The Night Watch</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1642, a huge group portrait</text></svg>","c":"Hallmarks of Rembrandt’s work"}]}});
